AUTO_SEED = 'auto'

@dataclass(frozen=True)
class ChordSpec:
    label: str
    root_offset: int
    intervals: Tuple[int, ...] = MINOR_TRIAD
    bass_offset: int | None = None
    tensions: Tuple[int, ...] = ()

    def sounding_bass_offset(self, pedal: bool) -> int:
        if self.bass_offset is not None:
            return self.bass_offset
        return 0 if pedal else self.root_offset

    def pitch_class_offsets(self, suspension: float) -> Tuple[int, ...]:
        offsets = [self.root_offset + interval for interval in self.intervals]
        if self.tensions and suspension > 0.0:
            keep = max(1, int(round(len(self.tensions) * min(1.0, suspension + 0.25))))
            offsets.extend((self.root_offset + tension for tension in self.tensions[:keep]))
        return tuple(offsets)

@dataclass(frozen=True)
class HarmonicSeed:
    name: str
    label: str
    summary: str
    mode: str
    progression: Tuple[ChordSpec, ...]
    cadence_chord: ChordSpec
    cadence_kind: str = 'aeolian'
    pedal: bool = True
    cadence_every: int = 4
    harmonic_rhythm_bars: int = 2
    pedal_bars: int = 8
    voicing_openness: float = 0.5
    suspension: float = 0.6
    max_voice_motion: int = 2
    pad_register: Tuple[int, int] = (55, 84)
    air_register: Tuple[int, int] = (79, 96)
    lead_octave_bias: int = 0
    tempo_bias: int = 0
    rule_sets: Tuple[str, ...] = ('balanced',)
    ca_rules: Tuple[int, ...] = (90, 110)
    phrase_lengths: Tuple[int, ...] = (8, 16)
    genre_affinity: Mapping[str, float] = field(default_factory=dict)

    def validate(self) -> None:
        if not self.progression:
            raise ValueError(f"Harmonic seed '{self.name}' needs at least one chord.")
        if self.cadence_kind not in CADENCE_KINDS:
            raise ValueError(f"Harmonic seed '{self.name}' has unknown cadence kind '{self.cadence_kind}'.")
        if self.harmonic_rhythm_bars <= 0:
            raise ValueError(f"Harmonic seed '{self.name}' harmonic_rhythm_bars must be positive.")
        if self.cadence_every <= 0:
            raise ValueError(f"Harmonic seed '{self.name}' cadence_every must be positive.")

    def affinity(self, genre: str) -> float:
        return float(self.genre_affinity.get(genre, 0.5))

    def chord_pitch_classes(self, tonic_pitch_class: int, index: int, suspension: float | None=None) -> List[int]:
        chord = self.chord_at(index)
        amount = self.suspension if suspension is None else suspension
        return sorted({(tonic_pitch_class + offset) % 12 for offset in chord.pitch_class_offsets(amount)})

    def chord_at(self, index: int) -> ChordSpec:
        if (index + 1) % self.cadence_every == 0:
            return self.cadence_chord
        return self.progression[index % len(self.progression)]

