HARMONIC_SEEDS: Dict[str, HarmonicSeed] = _seed_registry()

def available_harmonic_seeds() -> List[str]:
    return list(VALID_SEED_NAMES)

def get_harmonic_seed(name: str) -> HarmonicSeed:
    if name not in HARMONIC_SEEDS:
        choices = ', '.join(available_harmonic_seeds())
        raise ValueError(f"Unknown harmonic seed '{name}'. Choose one of: {choices}.")
    return HARMONIC_SEEDS[name]

def validate_seed_pool(pool: Sequence[str]) -> List[str]:
    if not pool:
        raise ValueError('A harmonic seed pool must contain at least one seed.')
    unknown = [name for name in pool if name not in HARMONIC_SEEDS]
    if unknown:
        choices = ', '.join(available_harmonic_seeds())
        raise ValueError(f"Unknown harmonic seeds: {', '.join(unknown)}. Choose from: {choices}.")
    return [name for name in VALID_SEED_NAMES if name in set(pool)]

def default_seed_pool(genre: str) -> List[str]:
    return sorted(VALID_SEED_NAMES, key=lambda name: (-HARMONIC_SEEDS[name].affinity(genre), VALID_SEED_NAMES.index(name)))

def species_allocation(pool: Sequence[str], population_size: int, genre: str='classic_trance') -> List[str]:
    ordered = validate_seed_pool(pool)
    if population_size <= 0:
        return []
    ranked = sorted(ordered, key=lambda name: (-HARMONIC_SEEDS[name].affinity(genre), ordered.index(name)))
    return [ranked[index % len(ranked)] for index in range(population_size)]

def seed_summary_rows(genre: str='classic_trance') -> List[Dict[str, object]]:
    rows: List[Dict[str, object]] = []
    for name in default_seed_pool(genre):
        seed = HARMONIC_SEEDS[name]
        rows.append({'name': seed.name, 'label': seed.label, 'summary': seed.summary, 'mode': seed.mode, 'cadence': seed.cadence_kind, 'pedal': seed.pedal, 'harmonic_rhythm_bars': seed.harmonic_rhythm_bars, 'progression': ' | '.join((chord.label for chord in seed.progression)), 'affinity': round(seed.affinity(genre), 2)})
    return rows
